import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"JavaScript Backend","description":"","frontmatter":{"title":"JavaScript Backend","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"web/project/adrs/0007-javascript-backend.md","filePath":"vendored/web/project/adrs/0007-javascript-backend.md"}`),a={name:`web/project/adrs/0007-javascript-backend.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="javascript-backend" tabindex="-1">JavaScript Backend <a class="header-anchor" href="#javascript-backend" aria-label="Permalink to “JavaScript Backend”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Architecture.</strong> .hnl source │ ▼ Kit (lex + parse) ← data-driven, same as always │ ▼ AST (handl-platform AstNode) │ ▼ handl-target-js ← new crate, walks AST → emits JS │ ▼ JavaScript source code │ ▼ Node.js / Browser / Edge</li><li><strong>Compilation strategy.</strong></li><li><strong>Arrow combinators as JS functions.</strong> The handl standard library combinators compile to plain JS functions:</li><li><strong>Loop compilation.</strong> Handl&#39;s <code>loop</code> is the most complex construct. It compiles to a JavaScript <code>while</code> loop with a state object:</li><li><strong>Pattern matching.</strong> Handl&#39;s <code>match</code> compiles to a JS function with type checks:</li><li><strong>Runtime prelude.</strong> The compiled JS includes a small prelude (~100 lines) containing:</li><li><strong>Output format.</strong> handl compile --target js arrows/fn/map.hnl -o map.js</li><li><strong>Source maps.</strong> The backend emits source map comments linking JS output back to <code>.hnl</code> source. This enables:</li><li><strong>Integration with existing infrastructure.</strong> The JS backend is a new <code>handl-target-js</code> crate that:</li><li><strong>What about refinement types?.</strong> The JS backend <strong>does not encode refinement types at runtime</strong>. Refinement types are a compile-time analysis — they guarantee correctness but don&#39;t change runtime behavior. The compiled JS is untyped (or optionally typed with JSDoc comments for TypeScript checking).</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Handl programs currently run only via the Rust tree-walking evaluator (<code>handl-plugin-engine-exec-tree-walk</code>). This limits handl to environments where a Rust binary can run. There is no way to:</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>WASM is harder to debug (no source maps, no readable output).</li><li>WASM can&#39;t directly manipulate the DOM or call JS APIs.</li><li>JS is more portable (runs in more environments than WASM).</li><li>A WASM backend can be added later by compiling the Rust evaluator to WASM (different approach, same result).</li><li>TypeScript adds type system complexity that doesn&#39;t map cleanly to handl&#39;s refinement types.</li><li>TypeScript can&#39;t be run directly in browsers or edge workers (requires compilation).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Run handl anywhere JS runs</strong> — browsers, Node.js, edge workers, Deno, Bun</li><li><strong>Web playground</strong> — compile handl to JS in the browser, no server needed</li><li><strong>npm packages</strong> — distribute handl programs as JS bundles</li><li><strong>Readable output</strong> — developers can inspect and debug the generated JS</li><li><strong>Source maps</strong> — stack traces and debugging point back to <code>.hnl</code> source</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (mechanism, tables, proofs, trade-offs): <a href="./../design/0007-javascript-backend.html"><code>design/0007-javascript-backend.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};